import{_ as n,a0 as d,w as p,s as o,I as s,x as e,a1 as t,A as l,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"終端基礎：在 Linux 中刪除文件和文件夾 | LCTT x X-CMD","titleTemplate":false,"description":"終端基礎：在 Linux 中刪除文件和文件夾 | LCTT (202305) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"終端基礎：在 Linux 中刪除文件和文件夾 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"終端基礎：在 Linux 中刪除文件和文件夾 | LCTT (202305) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202305/20230323.1 ⭐️ Terminal Basics 6 Delete Files and Folders in Linux","title":"終端基礎：在 Linux 中刪除文件和文件夾","tag":"202305","desc":""},"relativePath":"202305/20230323.1 ⭐️ Terminal Basics 6 Delete Files and Folders in Linux.md","filePath":"[post].md"}'),h={name:"202305/20230323.1 ⭐️ Terminal Basics 6 Delete Files and Folders in Linux.md"};function c(g,i,k,u,b,f){const a=d("Link");return p(),o("div",null,[i[20]||(i[20]=s("h1",{id:"終端基礎-在-linux-中刪除文件和文件夾",tabindex:"-1"},[e("終端基礎：在 Linux 中刪除文件和文件夾 "),s("a",{class:"header-anchor",href:"#終端基礎-在-linux-中刪除文件和文件夾","aria-label":"Permalink to “終端基礎：在 Linux 中刪除文件和文件夾”"},"​")],-1)),i[21]||(i[21]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202305/13/140619izbrl7owh9dr55lb.jpg",alt:""})],-1)),i[22]||(i[22]=s("blockquote",null,[s("p",null,"你已經學會了創建文件和目錄。現在是時候學習如何在命令列中刪除文件和文件夾了。")],-1)),s("p",null,[i[2]||(i[2]=e("在終端基礎系列的前幾章中，你學習了 ",-1)),t(a,{href:"https://linux.cn/article-15643-1.html"},{default:l(()=>[...i[0]||(i[0]=[e("創建新文件",-1)])]),_:1}),i[3]||(i[3]=e(" 和 ",-1)),t(a,{href:"https://linux.cn/article-15595-1.html"},{default:l(()=>[...i[1]||(i[1]=[e("目錄",-1)])]),_:1}),i[4]||(i[4]=e("（文件夾）。",-1))]),i[23]||(i[23]=r(`<p>現在讓我們看看如何在 Linux 終端中刪除文件和文件夾。</p><h3 id="刪除文件" tabindex="-1">刪除文件 <a class="header-anchor" href="#刪除文件" aria-label="Permalink to “刪除文件”">​</a></h3><p>要刪除文件，你可以按以下方式使用 <code>rm</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rm filename_or_path</span></span></code></pre></div><p>如果文件已成功刪除，你將看不到任何輸出。</p><p>這是一個示例，其中我刪除了一個名為 <code>new_file</code> 的文件。當我列出目錄內容時，你可以看到 <code>new_file</code> 不再存在。</p><p><img src="https://itsfoss.com/content/images/2023/03/delete-files-linux-terminal.png" alt="Removing files in Linux terminal"></p><p>你還可以在同一命令中刪除多個文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rm file1 file2 file3</span></span></code></pre></div><p>讓我展示一個在單條命令中刪除兩個文件的示例。</p><p><img src="https://itsfoss.com/content/images/2023/03/remove-multiple-files-linux-terminal.png" alt="Deleting multiple files in single rm command"></p><h4 id="🏋️練習文件刪除" tabindex="-1">🏋️練習文件刪除 <a class="header-anchor" href="#🏋️練習文件刪除" aria-label="Permalink to “🏋️練習文件刪除”">​</a></h4><p>讓我們練習一下剛剛學到的東西。創建一個名為 <code>practice_delete</code> 的目錄並切換到該目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir practice_delete &amp;&amp; cd practice_delete</span></span></code></pre></div><p>現在創建一些空文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>touch file1 file2 file3</span></span></code></pre></div><p>刪除 <code>file3</code>:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rm file3</span></span></code></pre></div><p>現在，讓我們做一些額外的事情。運行此命令並更改 <code>file2</code> 的權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>chmod u-w file1 file2</span></span></code></pre></div><p>現在嘗試刪除 <code>file2</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rm file2</span></span></code></pre></div><p>你是否看到消息 “<strong>remove write protected file</strong>”？ 那是因為你從這個文件中刪除了寫權限（用於修改）。</p><p>你可以<strong>按 <code>Y</code> 或回車鍵確認刪除或按 <code>N</code> 拒絕刪除。</strong></p><p>如果你不想看到這條消息並仍然刪除它，你可以使用強制刪除選項 <code>-f</code>。通過刪除 <code>file1</code> 試試：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rm -f file1</span></span></code></pre></div><p>以下是上述所有示例的重放：</p><p><img src="https://itsfoss.com/content/images/2023/03/file-delete-example.svg" alt="Deleting files in Linux terminal"></p><blockquote><p>🚧 Linux 命令列中沒有垃圾桶。一旦文件被刪除，你就無法像在圖形文件管理器中那樣撤消將其從垃圾箱中取回的操作。因此，刪除文件時要格外小心。</p></blockquote><h4 id="小心刪除" tabindex="-1">小心刪除 <a class="header-anchor" href="#小心刪除" aria-label="Permalink to “小心刪除”">​</a></h4><p>缺少垃圾桶使刪除成為一種永久性的工作。這就是為什麼你應該注意要刪除的文件的原因。</p><p>有一個帶 <code>-i</code> 選項的交互模式。有了這個，你會被要求確認刪除。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rm -i filename</span></span></code></pre></div><p>當你根據特定模式刪除多個文件時，這很有用。</p><p>這是一個示例，其中我以交互方式刪除名稱中匹配 <code>file_</code> 模式的所有文件。我刪除了一些並在交互模式下保留了一些。</p><p><img src="https://itsfoss.com/content/images/2023/03/interactive-delete-example.svg" alt="Deleting files in interactive mode"></p><blockquote><p>💡 我建議切換到文件所在的目錄，然後刪除它們。這有助於減少由文件路徑中的拼寫錯誤引起的任何可能性。</p></blockquote><h3 id="刪除目錄" tabindex="-1">刪除目錄 <a class="header-anchor" href="#刪除目錄" aria-label="Permalink to “刪除目錄”">​</a></h3><p>在 Linux 中有專門的 <code>rmdir</code> 命令來刪除目錄。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rmdir dir_name</span></span></code></pre></div><p>但是，它只能刪除空目錄。如果目錄中有任何文件或子目錄，<code>rmdir</code> 命令將拋出錯誤。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rmdir dir2</span></span>
<span class="line"><span>rmdir: failed to remove &#39;dir2&#39;: Directory not empty</span></span></code></pre></div><p>這使得它在大多數情況下用處不大。</p><p>那麼，如何刪除非空文件夾呢？ 好吧，使用與之前刪除文件相同的 <code>rm</code> 命令。</p><p>是的，相同的 <code>rm</code> 命令，但帶有遞歸選項 <code>-r</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rm -r dir_name</span></span></code></pre></div><h4 id="🏋️練習文件夾刪除" tabindex="-1">🏋️練習文件夾刪除 <a class="header-anchor" href="#🏋️練習文件夾刪除" aria-label="Permalink to “🏋️練習文件夾刪除”">​</a></h4><p>讓我們練習你學到的東西。</p><p>如果你還沒有，請切換到 <code>practice_delete</code> 文件夾。現在，創建兩個目錄 <code>dir1</code> 和 <code>dir2</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir dir1 dir2</span></span></code></pre></div><p>在 <code>dir2</code> 中創建一個文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>touch dir2/file</span></span></code></pre></div><p>現在嘗試使用 <code>rmdir</code> 命令刪除目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rmdir dir1</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rmdir dir2</span></span></code></pre></div><p>由於 <code>dir2</code> 不為空，<code>rmdir</code> 命令將失敗。相反，使用帶有遞歸選項的 <code>rm</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rm -r dir2</span></span></code></pre></div><p>以下是上述所有命令示例的重放：</p><p><img src="https://itsfoss.com/content/images/2023/03/folder-delete-example.svg" alt="Deleting folders in Linux"></p><blockquote><p>💡 交互式刪除模式在使用 <code>rm</code> 命令的遞歸選項刪除目錄時更有幫助：</p></blockquote><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rm-ri dir_name</span></span></code></pre></div><p>因此，你學會了使用 Linux 命令刪除文件和文件夾。是時候多練習了。</p><h3 id="測試你的知識" tabindex="-1">測試你的知識 <a class="header-anchor" href="#測試你的知識" aria-label="Permalink to “測試你的知識”">​</a></h3><p>準備一個如下所示的目錄樹：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.</span></span>
<span class="line"><span>├── dir1</span></span>
<span class="line"><span>│   ├── file1</span></span>
<span class="line"><span>│   ├── file2</span></span>
<span class="line"><span>│   └── file3</span></span>
<span class="line"><span>├── dir2</span></span>
<span class="line"><span>├── dir3</span></span>
<span class="line"><span>└── file</span></span></code></pre></div><p>基本上，你在當前目錄（<code>practice_delete</code>）中創建一個名為 <code>file</code> 的文件和三個目錄 <code>dir1</code>、<code>dir2</code> 和 <code>dir3</code>。然後在 <code>dir1</code> 中創建文件 <code>file1</code>、<code>file2</code> 和 <code>file3</code>。</p><p>現在執行以下操作：</p><ul><li>刪除 <code>file2</code>。</li><li>切換到 <code>dir3</code> 並強制刪除上層目錄中名為 <code>file</code> 的文件。</li><li>刪除 dir1 的所有內容，但不刪除目錄本身。</li><li>列出 <code>dir</code> 的內容。</li></ul><p>一切進展順利。你已經學習了一些基本知識，例如切換目錄、檢查目錄內容、創建和刪除文件和目錄。在下一章中，你將學習如何在終端中複製文件和文件夾。敬請關注！</p><hr>`,70)),s("p",null,[i[6]||(i[6]=e("via: ",-1)),t(a,{href:"https://itsfoss.com/delete-files-folders-linux/"},{default:l(()=>[...i[5]||(i[5]=[e("https://itsfoss.com/delete-files-folders-linux/",-1)])]),_:1})]),s("p",null,[i[11]||(i[11]=e("作者：",-1)),t(a,{href:"https://itsfoss.com/author/abhishek/"},{default:l(()=>[...i[7]||(i[7]=[e("Abhishek Prakash",-1)])]),_:1}),i[12]||(i[12]=e(" 選題：",-1)),t(a,{href:"https://github.com/lkxed/"},{default:l(()=>[...i[8]||(i[8]=[e("lkxed",-1)])]),_:1}),i[13]||(i[13]=e(" 譯者：",-1)),t(a,{href:"https://github.com/geekpi"},{default:l(()=>[...i[9]||(i[9]=[e("geekpi",-1)])]),_:1}),i[14]||(i[14]=e(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:l(()=>[...i[10]||(i[10]=[e("wxy",-1)])]),_:1})]),s("p",null,[i[17]||(i[17]=e("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...i[15]||(i[15]=[e("LCTT",-1)])]),_:1}),i[18]||(i[18]=e(" 原創編譯，",-1)),t(a,{href:"https://linux.cn/"},{default:l(()=>[...i[16]||(i[16]=[e("Linux中國",-1)])]),_:1}),i[19]||(i[19]=e(" 榮譽推出",-1))])])}const C=n(h,[["render",c]]);export{y as __pageData,C as default};
